class Superpower {
  #sound;                                               // #private: invisible to subclasses
  constructor(sound) { this.#sound = sound; }
  activate() { throw new Error('implement activate()'); }         // the sandbox method
  _playSound(id, volume = 1.0) { this.#sound.play(id, volume); }  // primitive: _ convention
  _spawnParticles(kind, count) { this.engine.fx.spawn(kind, count); }
}

class SkyLaunch extends Superpower {
  activate() { this._playSound(SOUND_SPROING); this._spawnParticles(PARTICLE_DUST, 10); }
}
